import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './CSS/Home.css';

function Home({ onSelectProduct }) {
  const navigate = useNavigate();
  const scrollRef1 = useRef(null);
  const scrollRef2 = useRef(null);
  const scrollRef3 = useRef(null);

  const [wishlistItems, setWishlistItems] = useState([]);
  const [showWishlistDropdown, setShowWishlistDropdown] = useState(false);

  // Load wishlist items on mount & listen for updates
  useEffect(() => {
    const fetchWishlist = () => {
      const saved = JSON.parse(localStorage.getItem('wishlistItems')) || [];
      setWishlistItems(saved);
    };

    fetchWishlist();
    window.addEventListener('wishlistUpdated', fetchWishlist);
    window.addEventListener('storage', fetchWishlist);

    return () => {
      window.removeEventListener('wishlistUpdated', fetchWishlist);
      window.removeEventListener('storage', fetchWishlist);
    };
  }, []);

  const handleRemoveFromWishlist = (id, e) => {
    e.stopPropagation();
    const updated = wishlistItems.filter(item => (item._id || item.id) !== id);
    setWishlistItems(updated);
    localStorage.setItem('wishlistItems', JSON.stringify(updated));
    window.dispatchEvent(new Event('wishlistUpdated'));
  };

  // Top Picks products
  const topPicks = [
    { 
      id: 1, 
      title: 'Pigeon Amaze Plus Electric Kettle', 
      price: '$499', 
      originalPrice: '$1,245', 
      rating: '4.0', 
      reviews: '179,344', 
      image: 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=500',
      description: 'Classic 1.5L electric kettle with stainless steel body, fast boiling, and automatic shut-off protection.',
      keyFeatures: ['1.5 Litre Capacity', 'Stainless Steel Body', 'Automatic Shut-Off', 'Cordless Operation']
    },
    { 
      id: 2, 
      title: 'Clazkit Water Bottle Stainless Steel', 
      price: '$159', 
      originalPrice: '$299', 
      rating: '4.0', 
      reviews: '2,383', 
      image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=500',
      description: 'Durable insulated water bottle designed to keep your beverages hot or cold throughout the day.',
      keyFeatures: ['Food Grade Stainless Steel', 'Leak-Proof Lid', 'Sweat-Free Design', 'Eco-Friendly']
    },
    { 
      id: 3, 
      title: 'GNASTAS Kitchen Utility Knife', 
      price: '$709', 
      originalPrice: '$1,499', 
      rating: '4.3', 
      reviews: '101', 
      image: 'https://images.unsplash.com/photo-1593618998160-e34014e67546?w=500',
      description: 'Precision-forged stainless steel utility knife offering exceptional sharpness and comfortable grip.',
      keyFeatures: ['High-Carbon Steel Blade', 'Ergonomic Handle', 'Rust Resistant', 'Multi-Purpose Kitchen Use']
    },
    { 
      id: 4, 
      title: 'Pigeon Kessel Multipurpose Kettle', 
      price: '$949', 
      originalPrice: '$1,695', 
      rating: '3.8', 
      reviews: '30,147', 
      image: 'https://images.unsplash.com/photo-1585515320310-259814833e62?w=500',
      description: 'Multipurpose kettle ideal for boiling water, cooking noodles, brewing tea, and preparing soups.',
      keyFeatures: ['Wide Mouth for Easy Cleaning', 'Variable Temperature Control', 'Boil-Dry Protection', 'Transparent Glass Lid']
    },
    { 
      id: 5, 
      title: 'Amazon Basics Electric Egg Boiler', 
      price: '$429', 
      originalPrice: '$650', 
      rating: '4.1', 
      reviews: '13,391', 
      image: 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=500',
      description: 'Quick and efficient egg boiler capable of cooking up to 7 eggs simultaneously with 3 firmness modes.',
      keyFeatures: ['Boils up to 7 Eggs', 'Auto Power Off', 'Over-Temperature Protection', 'Measuring Cup Included']
    },
    { 
      id: 6, 
      title: 'AERYS Digital Alarm Clock with LED', 
      price: '$284', 
      originalPrice: '$1,999', 
      rating: '3.9', 
      reviews: '7,947', 
      image: 'https://images.unsplash.com/photo-1563861826100-9cb868fdbe1c?w=500',
      description: 'Modern digital alarm clock featuring a clear LED display, brightness adjustment, and snooze function.',
      keyFeatures: ['Large LED Display', 'Adjustable Brightness', 'Snooze Function', 'USB Powered']
    },
    { 
      id: 7, 
      title: 'Noise Buds VS104 Truly Wireless', 
      price: '$999', 
      originalPrice: '$2,999', 
      rating: '4.2', 
      reviews: '45,210', 
      image: 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=500',
      description: 'Wireless earbuds delivering rich sound, deep bass, and prolonged battery backup for daily commuting.',
      keyFeatures: ['InstaCharge Technology', 'Deep Bass Sound', 'IPX5 Water Resistance', 'Touch Controls']
    },
    { 
      id: 8, 
      title: 'Milton Thermosteel Flip Lid Flask', 
      price: '$675', 
      originalPrice: '$999', 
      rating: '4.5', 
      reviews: '12,500', 
      image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=500',
      description: 'Vacuum insulated flask designed to preserve temperature for up to 24 hours.',
      keyFeatures: ['24 Hours Temperature Retention', 'Flip Lid Mechanism', 'Leak Proof', 'Compact & Travel Friendly']
    }
  ];

  // Browsing History products
  const browsingHistory = [
    { 
      id: 101, 
      title: 'iPhone Pro Max (2 TB) - Silver', 
      price: '$3,29,900', 
      rating: '4.5', 
      reviews: '15', 
      image: 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=500',
      description: 'Flagship smartphone featuring cinematic video recording, advanced camera control, and titanium finish.',
      keyFeatures: ['A18 Pro Chip', '48MP Fusion Camera System', 'All-Day Battery Life', 'Titanium Design']
    },
    { 
      id: 102, 
      title: 'SONISHA Women Floral Print Short Kurti', 
      price: '$440.82', 
      originalPrice: '$1,799', 
      rating: '4.0', 
      reviews: '14', 
      image: 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?w=500',
      description: 'Comfortable breathable cotton short kurti featuring vibrant floral prints for casual wear.',
      keyFeatures: ['100% Pure Cotton', 'Vibrant Floral Print', 'Skin Friendly Fabric', 'Easy Machine Wash']
    },
    { 
      id: 103, 
      title: 'Story@Home King Size Bedsheet', 
      price: '$849.00', 
      originalPrice: '$999', 
      rating: '4.2', 
      reviews: '33', 
      image: 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=500',
      description: 'Luxurious king-size bedsheet set crafted from ultra-soft cotton fabric with matching pillow covers.',
      keyFeatures: ['King Size Dimensions', 'Ultra Soft Fabric', 'Fade Resistant Colors', 'Includes 2 Pillow Covers']
    },
    { 
      id: 104, 
      title: '40W Dynamic Power Adapter with 60W Max', 
      price: '$4,490.00', 
      rating: '4.6', 
      reviews: '8', 
      image: 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=500',
      description: 'High-speed dual port power adapter with intelligent current distribution and surge protection.',
      keyFeatures: ['Fast Charging Output', 'Dual USB-C Ports', 'Overheat Protection', 'Compact Travel Design']
    },
    { 
      id: 105, 
      title: 'JBL Go 3 Portable Wireless Speaker', 
      price: '$2,999.00', 
      originalPrice: '$3,999', 
      rating: '4.6', 
      reviews: '18,400', 
      image: 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=500',
      description: 'Ultra-portable waterproof bluetooth speaker delivering surprisingly big JBL Pro Sound.',
      keyFeatures: ['IP67 Waterproof & Dustproof', 'Vibrant Styling', '5 Hours Playtime', 'Bluetooth 5.1']
    },
    { 
      id: 106, 
      title: 'Logitech Wireless Mouse M220', 
      price: '$695.00', 
      originalPrice: '$995', 
      rating: '4.4', 
      reviews: '32,100', 
      image: 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=500',
      description: 'Silent wireless mouse with advanced optical tracking and long-lasting battery life.',
      keyFeatures: ['Silent Clicking', '18-Month Battery Life', 'Plug-and-Play Nano Receiver', 'Comfortable Shape']
    },
    { 
      id: 107, 
      title: 'JETech Matte Case for iPhone Pro', 
      price: '$1,299.00', 
      originalPrice: '$2,099', 
      rating: '4.4', 
      reviews: '10,014', 
      image: 'https://images.unsplash.com/photo-1601784551446-20c9e07cdbdb?w=500',
      description: 'Translucent matte case offering robust drop protection and silky smooth anti-fingerprint grip.',
      keyFeatures: ['Translucent Matte Finish', 'Shockproof Edges', 'Anti-Fingerprint Coating', 'Wireless Charging Friendly']
    }
  ];

  // Related Items products (Added one more item at the end)
  const relatedItems = [
    { 
      id: 201, 
      title: 'boAt Rockerz 450 Bluetooth Headphones', 
      price: '$1,499', 
      originalPrice: '$3,990', 
      rating: '4.2', 
      reviews: '85,420', 
      image: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=500',
      description: 'On-ear wireless headphones engineered for immersive audio experience and supreme ergonomic comfort.',
      keyFeatures: ['40mm Dynamic Drivers', '15 Hours Playback', 'Padded Ear Cushions', 'Dual Mode Connectivity']
    },
    { 
      id: 202, 
      title: 'Fire-Boltt Phoenix Smart Watch', 
      price: '$1,199', 
      originalPrice: '$9,999', 
      rating: '4.1', 
      reviews: '42,150', 
      image: 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=500',
      description: 'Feature-packed smartwatch with Bluetooth calling, health trackers, and multiple sports modes.',
      keyFeatures: ['Bluetooth Calling', 'SpO2 & Heart Rate Monitoring', '120+ Sports Modes', 'HD Display']
    },
    { 
      id: 203, 
      title: 'Boldfit Yoga Mat with Carrying Strap', 
      price: '$699', 
      originalPrice: '$1,499', 
      rating: '4.3', 
      reviews: '11,400', 
      image: 'https://images.unsplash.com/photo-1601925260368-ae2f83cf8b7f?w=500',
      description: 'Anti-slip yoga mat providing optimal cushioning and stability for workouts and stretching sessions.',
      keyFeatures: ['Anti-Slip Texture', 'Tear Resistant Material', 'Includes Carrying Strap', 'Lightweight & Portable']
    },
    { 
      id: 204, 
      title: 'Portronics Adapto 20W Fast Charger', 
      price: '$349', 
      originalPrice: '$999', 
      rating: '4.1', 
      reviews: '9,820', 
      image: 'https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=500',
      description: 'Compact Wall Charger with fast power delivery to quickly juice up your mobile devices safely.',
      keyFeatures: ['20W Power Delivery', 'Smart Chip Protection', 'Universal Compatibility', 'Fire Retardant Body']
    },
    { 
      id: 205, 
      title: 'ZEBRONICS Zeb-County Bluetooth Speaker', 
      price: '$469', 
      originalPrice: '$799', 
      rating: '4.0', 
      reviews: '19,830', 
      image: 'https://images.unsplash.com/photo-1545454675-3531b543be5d?w=500',
      description: 'Portable wireless speaker supporting USB, Micro SD, and FM radio with clear sound output.',
      keyFeatures: ['Multi-Connectivity Options', 'Built-in FM Radio', 'Compact & Lightweight', 'Calling Functionality']
    },
    { 
      id: 206, 
      title: 'Milton Go Fit Steel Bottle 750ml', 
      price: '$499', 
      originalPrice: '$650', 
      rating: '4.5', 
      reviews: '5,120', 
      image: 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?w=500',
      description: 'Single-wall sleek steel water bottle designed for easy grip and hydration on the go.',
      keyFeatures: ['750ml Capacity', 'Single Wall Steel', 'Leak-Proof Cap', 'Rust Free Material']
    },
    { 
      id: 207, 
      title: 'Zebronics Zeb-Solaris Wireless Mouse', 
      price: '$399', 
      originalPrice: '$749', 
      rating: '4.0', 
      reviews: '4,150', 
      image: 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=500',
      description: 'Ergonomic wireless optical mouse with smooth scrolling and high precision tracking.',
      keyFeatures: ['Ergonomic Grip', 'High Precision Optical Sensor', 'Nano USB Receiver', 'Power Saving Mode']
    }
  ];

  const renderProductRow = (title, items, ref, pageInfo, darkTheme = false) => (
    <div className={`product-row-wrapper ${darkTheme ? 'dark-theme' : 'light-theme'}`}>
      <div className="product-row-header">
        <div className="product-header-left">
          <h2 className={`product-row-title ${darkTheme ? 'dark-title' : 'light-title'}`}>{title}</h2>
          <Link to="/products" className="explore-link">Explore more deals</Link>
        </div>
        {pageInfo && <span className="page-info-text">{pageInfo}</span>}
      </div>

      <div ref={ref} className="products-scroll-box">
        {items.map((product) => (
          <div 
            key={product.id} 
            className="product-card-item"
            onClick={() => onSelectProduct && onSelectProduct(product)}
            style={{ cursor: 'pointer' }}
          >
            <div className="product-image-box">
              <img src={product.image} alt={product.title} className="product-img" />
            </div>
            <p className="product-card-title">{product.title}</p>
            <div className="product-rating-box">
              <span className="product-stars">★★★★☆</span>
              <span className="product-reviews">{product.reviews}</span>
            </div>
            <div className="product-price-container">
              <span className="product-price-current">{product.price}</span>
              {product.originalPrice && <span className="product-price-original">{product.originalPrice}</span>}
            </div>
            <p className="product-delivery-text">FREE delivery <b>Thu, 1 Oct</b></p>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="home-page-container" style={{ position: 'relative' }}>
      
      {/* Top Wishlist Quick-Access Header Bar / Icon Container */}
      <div style={{
        position: 'absolute',
        top: '15px',
        right: '25px',
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
        gap: '20px'
      }}>
        <div style={{ position: 'relative' }}>
          {showWishlistDropdown && (
            <div style={{
              position: 'absolute',
              right: 0,
              top: '52px',
              width: '320px',
              backgroundColor: '#ffffff',
              borderRadius: '12px',
              boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.2)',
              border: '1px solid #e2e8f0',
              zIndex: 1000,
              padding: '16px',
              color: '#0f172a'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', borderBottom: '1px solid #f1f5f9', paddingBottom: '8px' }}>
                <h4 style={{ margin: 0, fontSize: '16px', fontWeight: 'bold' }}>My Wishlist ({wishlistItems.length})</h4>
                <button 
                  onClick={() => setShowWishlistDropdown(false)}
                  style={{ background: 'none', border: 'none', fontSize: '16px', cursor: 'pointer', color: '#64748b' }}
                >
                  &times;
                </button>
              </div>

              {wishlistItems.length === 0 ? (
                <p style={{ textAlign: 'center', color: '#64748b', fontSize: '14px', margin: '20px 0' }}>Your wishlist is empty.</p>
              ) : (
                <div style={{ maxHeight: '250px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
                  {wishlistItems.map((item) => (
                    <div 
                      key={item._id || item.id} 
                      style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '6px', borderRadius: '8px', background: '#f8fafc' }}
                    >
                      <img 
                        src={item.image || item.images?.[0]} 
                        alt={item.title || item.name} 
                        style={{ width: '45px', height: '45px', objectFit: 'contain', borderRadius: '6px', background: '#fff' }} 
                      />
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <p style={{ margin: 0, fontSize: '13px', fontWeight: '600', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          {item.title || item.name}
                        </p>
                        <span style={{ fontSize: '12px', color: '#6366f1', fontWeight: 'bold' }}>{item.price}</span>
                      </div>
                      <button 
                        onClick={(e) => handleRemoveFromWishlist(item._id || item.id, e)}
                        style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '14px', padding: '4px' }}
                        title="Remove"
                      >
                        <i className="fa-solid fa-trash"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <button 
                onClick={() => {
                  setShowWishlistDropdown(false);
                  navigate('/wishlist');
                }}
                style={{
                  width: '100%',
                  marginTop: '12px',
                  backgroundColor: '#130352',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '8px',
                  fontWeight: 'bold',
                  fontSize: '13px',
                  cursor: 'pointer'
                }}
              >
                View Full Wishlist Page
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Promotional Banner with Image */}
      <div className="home-hero-banner-box">
        <div className="hero-banner-content">
          <span className="hero-badge-tag">Sale is live</span>
          <h1 className="hero-main-title">Starting $49</h1>
          <h2 className="hero-sub-title">Home, kitchen, toys & outdoors</h2>
          <Link to="/products" className="hero-return-btn">
            Return to all deals
          </Link>
        </div>

        {/* Banner Image Box */}
        <div className="hero-banner-img-box">
          <img 
            src="https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=600" 
            alt="Promotion Banner" 
            className="hero-banner-img"
          />
        </div>
      </div>

      {/* 1. Top Picks Section (Dark Theme) */}
      {renderProductRow("Top picks", topPicks, scrollRef1, null, true)}

      {/* 2. Inspired by your browsing history Section */}
      {renderProductRow("Inspired by your browsing history", browsingHistory, scrollRef2, "Page 1 of 6", false)}

      {/* 3. Middle Offer Banner */}
      <div className="middle-promo-banner">
        <div>
          <span className="promo-badge">Limited Time Deal</span>
          <h2 className="promo-title">Up to 60% off | Electronics & Accessories</h2>
          <p className="promo-description">Explore top brands with no cost EMI and exchange offers.</p>
        </div>
        <Link to="/products" className="promo-shop-btn">
          Shop Now
        </Link>
      </div>

      {/* 4. Related to items you viewed Section */}
      {renderProductRow("Related to items you viewed", relatedItems, scrollRef3, "Page 1 of 6", false)}
    </div>
  );
}

export default Home;
